6f547511-55ce-43a6-97cc-2dc11c24273e question: {"type":"question","witnessId":"w1","text":"Fictional Mira, according to your approved account in E-001, who handed the sealed envelope to Fictional Ellis?","examination":"reexamination"}
b2a6137a-1b2a-4580-803a-e04b81248f72 testimony: {"type":"answer","witnessId":"w1","text":"As recorded in E-001, my approved account states: \"I saw Fictional Rowan hand the sealed envelope to Fictional Ellis.\" According to my account, Fictional Rowan is the person who handed the sealed envelope to Fictional Ellis. My approved account does not address any further point on that question.","sourceRefs":[{"evidenceId":"0e464be2-82b2-4ee6-a850-abf898be5abb","exhibitId":"E-001","attribution":"source"}],"questionEventId":"6f547511-55ce-43a6-97cc-2dc11c24273e","examination":"reexamination"}
a2a981e9-eed5-4460-9cd2-ac6a88066259 question: {"type":"question","witnessId":"w1","text":"Fictional Mira, according to your approved account in E-001, who received the sealed envelope?","examination":"reexamination"}
2ac4e075-e01d-47e3-96a9-25dbbae95f5d testimony: {"type":"answer","witnessId":"w1","text":"As recorded in E-001, my approved account states: \"I saw Fictional Rowan hand the sealed envelope to Fictional Ellis. I do not know what the envelope contained.\" According to my account, Fictional Ellis is the person who received the sealed envelope from Fictional Rowan. My approved account does not address any further point on that question.","sourceRefs":[{"evidenceId":"0e464be2-82b2-4ee6-a850-abf898be5abb","exhibitId":"E-001","attribution":"source"}],"questionEventId":"a2a981e9-eed5-4460-9cd2-ac6a88066259","examination":"reexamination"}
